def load() -> pd.DataFrame:
    df = pd.read_csv('data/environment/input/constitution_beach_datasheet.csv', skiprows=2)
    return df

def process(analyze_standard):
    df = analyze_standard.copy()

    # Check what the Tag values actually mean
    # Show samples with different tags and their enterococcus values
    return df[['Date', 'Tag', 'Enterococcus', 'Tag.1', 'Enterococcus.1', 'Tag.2', 'Enterococcus.2']].head(30)

def process(analyze_standard_correct):
    df = analyze_standard_correct.copy()

    # For each day, check which sampling points have valid data and their standard status
    mixed_count = 0

    for idx, row in df.iterrows():
        meets_std_1 = row['meets_std_1']
        meets_std_2 = row['meets_std_2']
        meets_std_3 = row['meets_std_3']

        # Collect valid (non-NaN) measurements for this day
        valid_measurements = []
        if pd.notna(meets_std_1):
            valid_measurements.append(meets_std_1)
        if pd.notna(meets_std_2):
            valid_measurements.append(meets_std_2)
        if pd.notna(meets_std_3):
            valid_measurements.append(meets_std_3)

        # Check if we have at least 2 measurements and if they're mixed (one meets, one doesn't)
        if len(valid_measurements) >= 2:
            has_meets = any(m == 1 for m in valid_measurements)
            has_not_meets = any(m == 0 for m in valid_measurements)

            if has_meets and has_not_meets:
                mixed_count += 1

    return pd.DataFrame({'mixed_days_count': [mixed_count]})
